interface ICounter { int Value { get; } void Inc(); }

struct Counter : ICounter
{
    public int Value { get; private set; }
    void ICounter.Inc() => Value++;   // explicit implementation
}

var c = new Counter();
// c.Inc();            // error CS1061
((ICounter)c).Inc();   // boxing: the copy grew, c.Value == 0
ICounter box = c;      // another box
box.Inc();             // box.Value == 1, but c.Value == 0

cards/6/code:
static void Bump<T>(ref T x) where T : ICounter => x.Inc();
static void BumpBoxed(ICounter x) => x.Inc();

var c = new Counter();
Bump(ref c);     // no box: c.Value == 1
BumpBoxed(c);    // a box: c.Value is still 1
